  traveltrust_faq_eyebrow: "Trip questions",
  traveltrust_faq_title: "FAQ",
  traveltrust_faq_intro:
    "TTG rules first, then custom-trip questions. On-chain and compliance details live in Help and Governance.",
  traveltrust_faq_intro_lead: "TTG rules first, then custom-trip questions. Details in ",
  traveltrust_faq_intro_mid: " and ",
  traveltrust_faq_intro_tail: ".",
  traveltrust_faq_q1: "Is this page a token or securities offering?",
  traveltrust_faq_a1:
    "No. Brand and protocol narrative only; trip deposits settle via Escrow in USDC—not a securities offer.",
  traveltrust_faq_q6: "Is acquiring TTG the same as paying a trip deposit?",
  traveltrust_faq_a6:
    "No. Deposits use order Escrow (USDC). TTG is the governance token—see Governance for exchange notes.",
  traveltrust_faq_q7: "Must I hold TTG to book a custom trip?",
  traveltrust_faq_a7:
    "No. Travelers pay via stablecoin Escrow; TTG and Country Pool are Target/roadmap and do not replace trip settlement.",
  traveltrust_faq_q8: "Is trip escrow funds safe?",
  traveltrust_faq_a8:
    "Where deployed, orders use on-chain Escrow and allowlisted stablecoins; you keep your wallet—the app orchestrates signing. See Help.",
  traveltrust_faq_q2: "Are the numbers live on-chain?",
  traveltrust_faq_a2:
    "Illustrative metrics are design review only. TTG batches and prices follow the published plan on this page — not live volume or on-chain sales.",
  traveltrust_faq_q3: "How do I connect a wallet?",
  traveltrust_faq_a3:
    "Connect from the hero when disconnected; manage address and network in the header. The TTG rules preview shows USDC→TTG; deposits use Order pay.",
  traveltrust_faq_q4: "Where are supported countries and fee parameters?",
  traveltrust_faq_a4:
    "Phase parameters and on-chain runtime disclosure live on Protocol parameters (/governance/params) — not a fundraising promise.",
  traveltrust_faq_a4_lead: "Full parameters are in the ",
  traveltrust_faq_a4_tail: " protocol reference — do not treat this page as a fundraising promise.",
  traveltrust_faq_q9: "How do settlement and release work?",
  traveltrust_faq_a9:
    "After mutual confirmation, escrow funding, trip completion, and (if applicable) ratings, funds release on-chain—not instantly on booking. See Help.",
  traveltrust_faq_q10: "How are disputes handled?",
  traveltrust_faq_a10: "Structured paths may use human arbitration then contract execution. See Help and Disputes.",
  traveltrust_faq_a10_lead: "Structured paths may use human arbitration then contract execution. See ",
  traveltrust_faq_a10_mid: " and ",
  traveltrust_faq_a10_disputes: "Disputes",
  traveltrust_faq_a10_tail: ".",
  traveltrust_faq_q11: "What do the five roles do?",
  traveltrust_faq_a11:
    "Traveler plans trips; Guide hosts; Merchant showcases; Acquisition carries cross-border; Region steward for governance. See Role theater above.",
