  traveltrust_token_title: "Token system (compliance framing)",
  /** 85 §14: three-layer narrative; charts only after legal review */
  traveltrust_token_intro:
    "Separate trip settlement, governance participation, and travel utility—do not conflate with fixed yield or securities-style promises.",
  traveltrust_token_layer_settlement_title: "Settlement",
  traveltrust_token_layer_settlement_body:
    "Travel order Escrow primarily settles in allowlisted stablecoins (e.g. USDC) in the current product slice; roadmap tokens must not be described as having replaced trip settlement currency.",
  traveltrust_token_layer_governance_title: "Governance",
  traveltrust_token_layer_governance_body:
    "TTG, Country Pool, and FeeRouter routing are documented as Target / roadmap in 82–84 and Runbook §7.1; allocatable fee numerators and fundraising tiers are different stories—do not mix them (84 §1.3).",
  traveltrust_token_layer_utility_title: "Travel utility",
  traveltrust_token_layer_utility_body:
    "Points, membership, or ecosystem utility are product / comms layers and must be distinguished from dividend-like claims; rights and obligations follow legal sign-off.",
  traveltrust_token_layers_note:
    "Charts for vesting or allocation ship only after legal review; this page does not promise fixed returns from holding any token.",
  traveltrust_allocation_title: "Genesis allocation notes",
  traveltrust_allocation_body:
    "Tier progress and remaining spots must match internal CRM and 84 when published. This page does not display live allocation bars until numbers are legally cleared.",
  traveltrust_allocation_slot_a: "Allocation slot A (placeholder)",
  traveltrust_allocation_slot_b: "Allocation slot B (placeholder)",
  traveltrust_allocation_slot_c: "Allocation slot C (placeholder)",
  traveltrust_allocation_row_status: "Allocation details coming soon",
  traveltrust_allocation_bar_indeterminate: "Indeterminate placeholder bar",
  traveltrust_allocation_row_hint:
    "Shimmer bars are decorative only. Real tier labels, caps, and fill levels ship only after 84 + CRM + legal sign-off.",
  traveltrust_allocation_cta_market: "Open marketplace meanwhile",
  traveltrust_map_title: "Global map (roadmap)",
  traveltrust_map_body:
    "Geographic expansion follows staged rollout; highlight countries only when the same list is approved for external comms (see 84 for the ten-country phase narrative).",
  traveltrust_map_visual_note:
    "Abstract grid and nodes are decorative only. Which regions are live depends on your deployment—use Help / network status, not this graphic.",
  traveltrust_sticky_region: "TravelTrust quick actions",
  traveltrust_sticky_more: "More links",
  traveltrust_sticky_dismiss: "Dismiss",
  traveltrust_settlementTitle: "Settlement & tokens (Trust / standing disclosure)",
  traveltrust_settlementBody:
    "On-chain travel order Escrow (MVP and current implementation) primarily uses allowlisted stablecoins (e.g. USDC) for settlement. Governance token (TTG) or Country Pool narratives, when shown as roadmap or fundraising layer, must be labeled Target and must not imply they have replaced order settlement currency.",
  traveltrust_feeRouter_section_title: "Platform fee routing (operators)",
  traveltrust_feeRouter_section_lead:
    "Creating escrow on-chain requires platform fee routing to be configured for this deployment. The check below reflects this browser session only—not a protocol funds claim.",
  traveltrust_quickExplainTitle: "How it works — three steps",
  traveltrust_step_book_title: "Book",
  traveltrust_step_book_body:
    "Create or choose an itinerary, align with your guide, and open a travel order with clear terms.",
  traveltrust_step_match_title: "Match",
  traveltrust_step_match_body:
    "Guides meet on-chain eligibility rules; both sides confirm the plan before funds move into Escrow.",
  traveltrust_step_travel_title: "Travel & settle",
  traveltrust_step_travel_body:
    "Execute the trip; completion is confirmed off-chain first. Release uses the smart contract path when applicable—not the same as a single “done” tap.",
  traveltrust_quickExplain_footnote:
    "Happy path in production docs: off-chain confirm-completion → rating where applicable → on-chain release. See 01 / 53 for the authoritative flow.",
  traveltrust_problem_title: "Why travel rails matter",
  traveltrust_problem_body:
    "Cross-border payouts, unclear platform economics, and weak recourse when itineraries change or disputes arise.",
  traveltrust_solution_title: "What TravelTrust adds",
  traveltrust_solution_body:
    "Order-centric Escrow, guide staking and registry where deployed, and separate governance economics documented in 82–84—without conflating roadmap tokens with trip settlement.",
  traveltrust_highlights_title: "Core capabilities",
  traveltrust_matrix_title: "Problem vs response",
  traveltrust_matrix_lead:
    "Left: market context. Right: protocol and product response—for understanding only, not investment advice.",
  traveltrust_highlight_escrow_title: "Escrow & settlement",
  traveltrust_highlight_escrow_body:
    "Trip funds go into on-chain Escrow with release ordered per 01/53; settlement uses allowlisted stablecoins—roadmap tokens are not described as having replaced trip settlement.",
  traveltrust_highlight_match_title: "Matching & identity",
  traveltrust_highlight_match_body:
    "Guide eligibility and calendar rules use Registry; primary matching is the marketplace, with off-chain confirmation separate from on-chain funding.",
  traveltrust_highlight_gov_title: "Governance economics",
  traveltrust_highlight_gov_body:
    "TTG, Country Pool, and FeeRouter follow 82–84; fundraising tiers and allocatable fee numerators are different stories—do not mix them (84 §1.3).",
  traveltrust_highlight_trust_title: "Disputes & trust",
  traveltrust_highlight_trust_body:
    "Dispute and arbitration paths follow product specs; motion and stats here are illustrative, not live on-chain volume or TVL.",
  traveltrust_quick_section_eyebrow: "Product path",
