  traveltrust_nav_cta: "CTA",
  traveltrust_trust_title: "Trust & facts",
  traveltrust_trust_body:
    "Orders settle in allowlisted stablecoins on EVM L2 for the current product slice. Anything marked Target (e.g. TTG, Country Pool, FeeRouter extensions) is roadmap unless your deployment says otherwise.",
  traveltrust_trust_bullet_escrow:
    "Trip funds use on-chain Escrow; release follows 01 / 53—trip completion confirmation, rating where applicable, bilateral confirmations, then on-chain release.",
  traveltrust_trust_bullet_allowlist:
    "Trip settlement favors allowlisted stablecoins; token allowlists and contracts follow your deployment configuration.",
  traveltrust_trust_bullet_guide:
    "Guide acceptance and slot rules follow product constraints; staking and Registry follow deployed contracts (see 81 / 08-3 narrative split).",
  traveltrust_trust_bullet_disputes:
    "Disputes align with 01 / 03—structured paths, human resolution, and contract execution where configured; see /disputes and /help.",
  traveltrust_trust_bullet_target:
    "Motion and demo numbers are illustrative, not live chain truth; DAO, regional pools, and fee-routing extensions must read as Target or pre-deploy non-commitments (13-1 table 2-continued, 83 appendix I.0).",
  traveltrust_cta_title: "Explore the live product",
  traveltrust_cta_body: "No simulated checkout here—use the same app paths as travelers and guides.",
  traveltrust_cta_market: "Open marketplace",
  traveltrust_cta_home: "Main experience",
  /** Anchor `#fee-router` — 07 §5.3A + §5.2A */
  traveltrust_link_feeRouter: "FeeRouter check",
  /** Help links to `/governance` (v6 has no `#token-system` on /traveltrust) */
  traveltrust_link_tokenSystem: "Token layers",
  traveltrust_legacy_faq_title: "FAQ",
  traveltrust_legacy_faq_intro:
    "Plain-language answers; for legal or jurisdiction-specific wording, follow the signed text when published.",
  traveltrust_legacy_faq_q1: "Is trip money safe?",
  traveltrust_legacy_faq_a1:
    "Travel orders use on-chain escrow with stablecoins. You keep wallet custody; the app orchestrates signing. Exact non-custody boundaries are in the help center.",
  traveltrust_legacy_faq_q2: "Do I need a special token to book a trip?",
  traveltrust_legacy_faq_a2:
    "The live product path settles in allowlisted stablecoins (e.g. USDC) on EVM L2. TTG, Country Pool, or FeeRouter extensions are documented as Target / roadmap in 82–84 and must not be read as replacing trip settlement currency.",
  traveltrust_legacy_faq_q3: "How does settlement and release work?",
  traveltrust_legacy_faq_a3:
    "Flow follows 01 / 53: bilateral confirmation, Escrow funding, off-chain trip completion confirmation, rating where applicable, then on-chain release when conditions are met—not a single “done” button that equals payout.",
  traveltrust_legacy_faq_q4: "Is a given chain or feature already live?",
  traveltrust_legacy_faq_a4:
    "Depends on your deployment. Use Help, network status, and governance parameters for live runtime truth; this page is narrative, not a live status board.",
  traveltrust_legacy_faq_q5: "How are disputes handled?",
  traveltrust_legacy_faq_a5:
    "Disputes align with 01 / 03: structured paths and, where configured, human resolution followed by contract execution. See /disputes and /help for product entry points.",
  traveltrust_legacy_faq_visual_note:
    "Any future motion graphics on this page are illustrative; they are not real-time on-chain trade confirmations.",
