  help_title: "Help",
  help_desc:
    "Platform notes, FAQ and legal entry points; full legal text is the published Terms of Service and Privacy Policy.",
  help_platform: "Platform & funds",
  help_disputes: "Appeals & disputes",
  help_terms: "Terms of Service",
  help_privacy: "Privacy Policy",
  help_termsIntro: "Full rules and legal wording: ",
  help_docNote: "; version and effective dates follow legal sign-off.",
  help_backHome: "Back to home",
  help_platformBullet1: "TravelTrust helps travelers book safely: trip funds stay protected until the trip is completed; the platform does not take or hold your trip money.",
  help_platformBullet2: "Multisig has Pause/freeze capability for ops and security; Pause only suspends on-chain transfers and does not transfer asset ownership.",
  help_platformBullet3:
    "The platform uses hybrid governance today (multisig safeguards, human arbitration, and similar controls). See the Terms of Service for details.",
  help_disputesParagraph:
    "Disputes, evidence and arbitration follow the Terms of Service. When on-chain outflows are paused you can usually view orders and balances and submit appeal materials; you cannot create new orders or complete on-chain outflows. Recovery and exceptions are in the Terms.",
  help_faqTitle: "FAQ",
  help_faqPayQ: "How do I pay and open escrow details?",
  help_faqPayA:
    "After checkout and payment steps from Orders, use the Pay hub for a short checklist and jump to order details at /escrow/{order UUID}. Payment, completion and disputes follow the page and require wallet signatures where indicated.",
  help_faqPayCta: "Trip payment guide",
  help_faqPayDeepLink:
    "Deep link: /pay?orderId=<order UUID> prefills the id and shows the Open order details button (replace the placeholder with your order UUID).",
  help_faqStakingQ: "Where is guide staking and registry?",
  help_faqStakingA: "Staking and registry eligibility use on-chain contracts; the page explains risks and entry points—use a compatible wallet and network.",
  help_faqStakingCta: "Staking & apply",
  help_faqEscrowQ: "I cannot find the order details page.",
  help_faqEscrowA: "Order details are at /escrow/{order UUID}. Copy the order id from My orders or enter it on the Pay hub to navigate.",
  help_faqEscrowCta: "My orders",
  help_faqFeeRouterQ: "Escrow creation fails with a platform fee or contract configuration error?",
  help_faqFeeRouterA:
    "If escrow creation fails with a platform-fee configuration message, your session may not match the deployed contract wiring. Retry later or contact support; operators can review fee-route notes in the governance portal.",
  help_faqDisputeQ: "What if there is a dispute?",
  help_faqDisputeA: "Use Disputes for status and evidence notes; binding rules are in the Terms of Service.",
  help_faqDisputeCta: "Disputes",
  help_faqCommunityQ: "Where is community / trip chat?",
  help_faqCommunityA: "TT Community and order messages support itinerary confirmation and coordination; available features match the current UI.",
  help_faqCommunityCta: "TT Community intro",
  help_faqCommunityCtaFeed: "Browse community feed",
  help_feedbackTitle: "Suggestions & official feedback",
  help_feedbackDesc:
    "To request new attractions or dining options, or share product ideas, use the TT Community feedback page (same sign-in as the rest of the site).",

  terms_title: "Terms of Service",
  terms_intro: "Core wording aligns with TravelTrust 08-4. Full terms subject to legal; document version and date see 08-4.",
  terms_section1Title: "1. Who we are",
  terms_section1Bullet1: "TravelTrust is a travel booking platform that protects trip funds in escrow until completion and uses verifiable reputation; we do not take or hold your trip money.",
  terms_section1Bullet2: "Contract: traveler ↔ guide; platform is intermediary.",
  terms_section1Bullet3: "Current phase: hybrid governance (multisig + human arbitration + Pause + Runbook); not permissionless only.",
  terms_section2Title: "2. Funds and custody",
  terms_section2Bullet1: "The platform does not custody user funds; funds are in on-chain Escrow; users sign transactions.",
  terms_section2Bullet2: "Multisig Pause/freeze is for ops and security; Pause only suspends on-chain transfers and does not transfer ownership.",
  terms_footerNote: "By using TravelTrust you agree to the above and local laws. Full terms, arbitration and compliance see legal.",
  terms_backHome: "Back to home",

  privacy_title: "Privacy Policy",
  privacy_intro: "Core wording aligns with TravelTrust 08-4. Full policy subject to legal; document version and date see 08-4.",
  privacy_section1Title: "1. Evidence and data retention",
  privacy_section1Bullet1: "Dispute evidence: originals may be deleted after retention; hash + receipt retained for proof of existence, time, parties; no reversible originals.",
  privacy_section1Bullet2: "DID, passport and other sensitive data: encrypted, access control, retention and deletion per legal and local privacy laws.",
  privacy_section2Title: "2. Data sovereignty and cross-border",
  privacy_section2Bullet1: "Cross-border or EU evidence must meet applicable data rules (e.g. GDPR, localization).",
  privacy_section2Bullet2: "Data sovereignty, DPA, governing law, data controller per legal and Runbook.",
  privacy_footerNote: "By using TravelTrust you acknowledge the above. Full privacy policy (including right to be forgotten, hash and GDPR) see legal.",
  privacy_backHome: "Back to home",

  disputes_listTitle: "Disputes",
